        public Input<bool>? Exportable { get; set; }

        /// <summary>
        /// The hash function used for the RSA-OAEP step of creating the ciphertext (`SHA1`, `SHA224`, `SHA256`, `SHA384`, `SHA512`). Vault uses `SHA256` if not set. Vault does not store this value; it is only used to unwrap the ciphertext in each request, so it is sent to Vault every time `CiphertextWo` is sent (on create and whenever `CiphertextWoVersion` changes).
        /// </summary>
        [Input("hashFunction")]
        public Input<string>? HashFunction { get; set; }

        /// <summary>
        /// Changes the key type of the new key version when importing key material into an existing key. The usage of the new type must match the usage of the existing type. Sent to Vault as `Type` on the import key version endpoint, so it has no effect on the initial import. The result is shown in `LatestVersionType`; `Type` remains the original key type. *Available only for Vault Enterprise 2.2 or later*.
        /// </summary>
        [Input("importVersionType")]
        public Input<string>? ImportVersionType { get; set; }

        /// <summary>
        /// Whether the key was imported into Vault (as opposed to generated by Vault).
        /// </summary>
        [Input("importedKey")]
        public Input<bool>? ImportedKey { get; set; }

        /// <summary>
        /// Whether the imported key is configured to allow rotation.
        /// </summary>
        [Input("importedKeyAllowRotation")]
        public Input<bool>? ImportedKeyAllowRotation { get; set; }

        [Input("keys")]
        private InputMap<string>? _keys;

        /// <summary>
        /// Map of key version to its metadata in the keyring.
        /// </summary>
        public InputMap<string> Keys
        {
            get => _keys ?? (_keys = new InputMap<string>());
            set => _keys = value;
        }

        /// <summary>
        /// Latest key version in use in the keyring.
        /// </summary>
        [Input("latestVersion")]
        public Input<int>? LatestVersion { get; set; }

        /// <summary>
        /// The key type of the latest key version in the keyring. *Available only for Vault 2.2 or later*.
        /// </summary>
        [Input("latestVersionType")]
        public Input<string>? LatestVersionType { get; set; }

        /// <summary>
        /// Minimum key version available for use.
        /// </summary>
        [Input("minAvailableVersion")]
        public Input<int>? MinAvailableVersion { get; set; }

        /// <summary>
        /// Minimum key version to use for decryption. Vault always sets this to at least `1`. Can be updated in place.
        /// </summary>
        [Input("minDecryptionVersion")]
        public Input<int>? MinDecryptionVersion { get; set; }

        /// <summary>
        /// Minimum key version to use for encryption. Can be updated in place.
        /// </summary>
        [Input("minEncryptionVersion")]
        public Input<int>? MinEncryptionVersion { get; set; }

        /// <summary>
        /// Path where the Transit secret backend is mounted. Changing this forces a new resource.
        /// </summary>
        [Input("mount")]
        public Input<string>? Mount { get; set; }

        /// <summary>
        /// Name of the encryption key to create. Changing this forces a new resource.
        /// </summary>
        [Input("name")]
        public Input<string>? Name { get; set; }

        /// <summary>
        /// The namespace to provision the resource in.
        /// The value should not contain leading or trailing forward slashes.
        /// The `Namespace` is always relative to the provider's configured [namespace](https://www.terraform.io/docs/providers/vault/index.html#namespace).
        /// *Available only for Vault Enterprise*.
        /// </summary>
        [Input("namespace")]
        public Input<string>? Namespace { get; set; }

        /// <summary>
        /// A plaintext PEM public key to be imported for public-key-only import. Changing this imports the new public key as a new key version. Vault requires either this or `CiphertextWo` for the initial import. Removing it from the configuration plans a one-time in-place update to clear it from state and does not change the key.
        /// </summary>
        [Input("publicKey")]
        public Input<string>? PublicKey { get; set; }

        /// <summary>
        /// Whether the key supports decryption.
        /// </summary>
        [Input("supportsDecryption")]
        public Input<bool>? SupportsDecryption { get; set; }

        /// <summary>
        /// Whether the key supports derivation.
        /// </summary>
        [Input("supportsDerivation")]
        public Input<bool>? SupportsDerivation { get; set; }

        /// <summary>
        /// Whether the key supports encryption.
        /// </summary>
        [Input("supportsEncryption")]
        public Input<bool>? SupportsEncryption { get; set; }

        /// <summary>
        /// Whether the key supports signing.
        /// </summary>
        [Input("supportsSigning")]
        public Input<bool>? SupportsSigning { get; set; }

        /// <summary>
        /// Specifies the type of key to create. Supported types: `aes128-gcm96`, `aes256-gcm96`, `chacha20-poly1305`, `Ed25519`, `ecdsa-p256`, `ecdsa-p384`, `ecdsa-p521`, `rsa-2048`, `rsa-3072`, `rsa-4096`, `Hmac`, `aes128-cmac`, `aes192-cmac`, `aes256-cmac`. Changing this forces a new resource.
        /// </summary>
        [Input("type")]
        public Input<string>? Type { get; set; }

        /// <summary>
        /// The existing key version to update when importing key material into an already-imported key. If omitted, Vault creates a new version, except when the latest version contains only a public key and the new ciphertext supplies its matching private key; in that case Vault adds the private key to that existing version. Ignored when the key is first imported.
        /// &gt; **Note:** `Version` is sent to Vault whenever key material is imported, so each time you bump `CiphertextWoVersion`, either remove `Version` from the configuration (to target the latest version) or set it to the key version you want to add private key material to. Leaving a previous value in place targets that same version again.
        /// </summary>
        [Input("version")]
        public Input<int>? Version { get; set; }

        public SecretBackendImportedKeyState()
        {
        }
        public static new SecretBackendImportedKeyState Empty => new SecretBackendImportedKeyState();
    }
}
